import { computed, toValue, type MaybeRefOrGetter } from 'vue'
import { useAsyncData, useNuxtApp } from '#imports'
// Virtual module generated by this module's `setup()`; only resolvable inside a real Nuxt build.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import { tabs as registry } from '#widgets/tabs'
import type { RegisteredTab, TabMeta } from '../../../types'
import { sortWidgets } from '../../utils/sort'

// `@nuxtjs/i18n` is optional: duck-type the `$i18n` plugin it injects instead of depending on it.
type NuxtAppWithI18n = {
  $i18n?: { locale?: { value: string }, t?: (key: string) => string, te?: (key: string) => boolean }
}

/**
 * The tabs registered for an area, ordered, with labels translated (`labelKey`, falling back to `label`, then
 * the id) and passed through the `tabs:filter` hook, as plain data (the component itself is resolved by
 * `<WidgetTabs>`). `context` is whatever the host renders the area for (e.g. `{ user }`) and is handed to the
 * filter listeners. Same return shape as `useAsyncData`.
 */
export function useTabs(area: string, context?: MaybeRefOrGetter<Record<string, unknown> | undefined>) {
  const nuxtApp = useNuxtApp()
  const i18n = (nuxtApp as unknown as NuxtAppWithI18n).$i18n
  const locale = computed(() => i18n?.locale?.value)

  return useAsyncData(`tabs:${area}`, async () => {
    const tabs: TabMeta[] = sortWidgets((registry[area] ?? []) as unknown as Array<RegisteredTab & { component: unknown }>)
      .map(({ component: _component, label, labelKey, ...meta }) => ({
        ...meta,
        labelKey,
        label: (labelKey && i18n?.te?.(labelKey) ? i18n.t?.(labelKey) : undefined) ?? label ?? meta.id,
      }))
    const ctx = { area, tabs, context: toValue(context) }
    await nuxtApp.callHook('tabs:filter', ctx)
    return ctx.tabs
  }, { watch: [locale] })
}
